from __future__ import annotations

from app.platform.ui.founder_dashboard_stable import render_stable_founder_dashboard


def render_board_chat_dashboard() -> str:
    html = render_stable_founder_dashboard()
    html = html.replace("<button class='primary' onclick='openBoardRoom()'>Start Discussion</button>", "<button class='primary' onclick='newBoardChat()'>New Chat</button>")
    html = html.replace("<h2>Board Room Discussion</h2><button class='secondary' onclick='closeBoardRoom()'>Close</button>", "<h2>Board Room Executive Chat</h2><div><button class='secondary' onclick='newBoardChat()'>New Chat</button> <button class='secondary' onclick='closeBoardRoom()'>Close</button></div>")
    html = html.replace("<textarea id='message' placeholder='Tell the Board Room what you want to discuss.'></textarea>", "<div class='board-chat-note'>Chat starts as normal conversation. Mission Control only suggests a mission when the conversation clearly becomes execution work.</div><textarea id='message' placeholder='Message the Board Room...' rows='3'></textarea>")
    html = html.replace("Start Board Room Discussion", "Send")
    html = html.replace("Create Proposal From Discussion", "Generate Workflow")
    html = html.replace("<h3>Board Room Response</h3><pre id='result'>Type a message and start the discussion.</pre>", "<div class='board-chat-grid'><section><div class='board-mode-strip'><span id='conversationMode' class='mode-pill'>General Conversation</span><span id='missionSuggestion' class='small'>No mission suggested</span></div><h3>Chat</h3><pre id='result'>Start a new Board Room chat.</pre></section><aside class='board-minutes'><h3>Conversation Intelligence</h3><p><strong>Mode</strong></p><p id='modeDescription' class='muted'>General clarification or discussion. No execution required.</p><p><strong>Decisions</strong></p><ul id='decisionMinutes'><li>No decisions captured yet.</li></ul><p><strong>Actions</strong></p><ul id='actionMinutes'><li>No actions captured yet.</li></ul><p><strong>Knowledge</strong></p><ul id='knowledgeMinutes'><li>Important context will appear here.</li></ul><div id='missionCard' class='mission-card muted'>Mission promotion will appear here only when appropriate.</div><div id='workflowCard' class='mission-card muted'>Workflow card will appear after Generate Workflow.</div><p id='meetingMeta' class='muted'>No meeting yet.</p></aside></div>")
    html = html.replace("</style>", ".board-chat-note{border:1px solid var(--line);background:#07101e;border-radius:12px;padding:12px;margin-bottom:12px;color:var(--muted)}.board-chat-grid{display:grid;grid-template-columns:minmax(0,1fr) 340px;gap:14px}.board-minutes{border:1px solid var(--line);border-radius:12px;padding:14px;background:#07101e}.board-minutes ul{padding-left:18px;color:#dbeafe}.board-minutes li{margin:6px 0}.board-mode-strip{display:flex;gap:10px;align-items:center;flex-wrap:wrap}.mode-pill{display:inline-flex;border:1px solid #334155;background:#102846;border-radius:999px;padding:6px 10px;color:#dbeafe;font-size:12px;font-weight:800}.mission-card{border:1px solid var(--line);border-radius:12px;padding:12px;margin:14px 0;background:#0b1628}.mission-card.ready{border-color:#6d28d9;color:#f2f7ff}.workflow-stage{display:flex;gap:7px;align-items:center;margin:5px 0;color:#dbeafe}.workflow-stage.complete{color:#22c55e}.workflow-stage.current{color:#fbbf24;font-weight:800}.workflow-actions{display:flex;gap:8px;flex-wrap:wrap;margin-top:10px}.workflow-actions button{padding:8px 10px;border-radius:10px}@media(max-width:900px){.board-chat-grid{grid-template-columns:1fr}}\n</style>")
    html = html.replace("window.openBoardRoom=function(){byId('boardModal').classList.add('active')};window.closeBoardRoom=function(){byId('boardModal').classList.remove('active')};window.startCommand=function(){byId('message').value=byId('commandInput').value||'';openBoardRoom()};", JS_REPLACEMENT)
    html = html.replace("if(data.board_room_response){var response=data.board_room_response+'\\n\\n---\\nMeeting ID: '+data.meeting_id+'\\nStatus: '+data.status;show(response);fillMinutes(data.board_room_response,'Meeting ID: '+data.meeting_id+' · Status: '+data.status)}else{show(data);fillMinutes(JSON.stringify(data),'Status: response-ready')}", "if(data.board_room_response){var response=data.board_room_response+'\\n\\n---\\nMeeting ID: '+data.meeting_id+'\\nStatus: '+data.status;show(response);if(data.conversation_intelligence)renderConversationIntelligence(data.conversation_intelligence,'Meeting ID: '+data.meeting_id+' · Status: '+data.status);else fillMinutes(byId('message').value+'\\n'+data.board_room_response,'Meeting ID: '+data.meeting_id+' · Status: '+data.status)}else{show(data);if(data.conversation_intelligence)renderConversationIntelligence(data.conversation_intelligence,'Status: response-ready');else fillMinutes(byId('message').value+'\\n'+JSON.stringify(data),'Status: response-ready')}")
    html = html.replace("window.createWorkflow=async function(){show('Creating proposal from Board Room discussion...');try{var data=await post('/mission-control/operating-console/workflow',{token:token,action:'create-proposal',message:byId('message').value});show(data)}catch(e){show('Workflow request failed: '+e)}};", "window.createWorkflow=async function(){show('Generating workflow from Board Room discussion...');try{var data=await post('/mission-control/operating-console/workflow',{token:token,action:'create-proposal',message:byId('message').value});show(data);if(data.conversation_intelligence)renderConversationIntelligence(data.conversation_intelligence,'Workflow generated');if(data.founder_workflow)renderWorkflowCard(data.founder_workflow)}catch(e){show('Workflow request failed: '+e)}};")
    html = html.replace("window.createWorkflow=async function(){show('Generating workflow from Board Room discussion...');try{var data=await post('/mission-control/operating-console/workflow',{token:token,action:'create-proposal',message:byId('message').value});show(data);if(data.founder_workflow)renderWorkflowCard(data.founder_workflow)}catch(e){show('Workflow request failed: '+e)}};", "window.createWorkflow=async function(){show('Generating workflow from Board Room discussion...');try{var data=await post('/mission-control/operating-console/workflow',{token:token,action:'create-proposal',message:byId('message').value});show(data);if(data.conversation_intelligence)renderConversationIntelligence(data.conversation_intelligence,'Workflow generated');if(data.founder_workflow)renderWorkflowCard(data.founder_workflow)}catch(e){show('Workflow request failed: '+e)}};")
    return html


JS_REPLACEMENT = """function setItems(id,items,empty){var el=byId(id);if(!el)return;el.innerHTML='';(items&&items.length?items:[empty]).slice(0,6).forEach(function(s){var li=document.createElement('li');li.textContent=s;el.appendChild(li)})}
function renderConversationIntelligence(ci,meeting){if(!ci)return;var pill=byId('conversationMode');if(pill)pill.textContent=ci.mode||'General Conversation';var desc=byId('modeDescription');if(desc)desc.textContent=(ci.recommended_next_action||'Review conversation.')+(ci.confidence?' Confidence '+ci.confidence:'');var suggest=byId('missionSuggestion');if(suggest)suggest.textContent=ci.mission_required?'Mission suggested':'No mission suggested';setItems('decisionMinutes',ci.decisions,'No decisions captured yet.');setItems('actionMinutes',ci.actions,'No actions captured yet.');setItems('knowledgeMinutes',ci.knowledge,'Important context will appear here.');var card=byId('missionCard');if(card){card.className='mission-card '+(ci.mission_required?'ready':'muted');card.textContent=ci.mission_suggestion&&ci.mission_suggestion.suggested?'Suggested: '+ci.mission_suggestion.title:'Working note only. Do not auto-create a mission.'}var meta=byId('meetingMeta');if(meta)meta.textContent=meeting||'No meeting yet.'}
function classifyConversation(text){var t=String(text||'').toLowerCase();if(/deploy|production|cloud run|release|rollback/.test(t))return ['Deployment','Operational deployment or release conversation.','Promote only if Founder asks to deploy or rollback.'];if(/implement|build|fix|code|create pr|open pr|github|merge/.test(t))return ['Engineering Mission','Execution request detected.','Suggest creating a mission after Founder confirms scope.'];if(/architecture|refactor|technical debt|frontend|backend|template|static js/.test(t))return ['Architecture','Architecture discussion.','Can become a mission if implementation is requested.'];if(/strategy|roadmap|market|fundraising|pricing|positioning/.test(t))return ['Strategy','Strategic discussion.','Save as working note unless Founder asks for execution.'];if(/review|audit|check|validate/.test(t))return ['Review','Review or audit conversation.','Create a mission only if changes are approved.'];if(/why|what is|explain|clarify|how does/.test(t))return ['Knowledge','Clarification or knowledge request.','No mission needed.'];return ['General Conversation','General discussion. No execution required.','No mission suggested'];}
function renderWorkflowCard(wf){var card=byId('workflowCard');if(!card||!wf)return;card.className='mission-card ready';var html='<strong>'+wf.title+'</strong><br><span class="small">'+wf.status+' · '+wf.workflow_id+'</span>';if(wf.stages){html+='<div style="margin-top:10px">';wf.stages.forEach(function(s){html+='<div class="workflow-stage '+s.state+'">'+(s.state==='complete'?'✓':s.state==='current'?'●':'○')+' '+s.label+'</div>'});html+='</div>'}html+='<p class="muted">Next: '+wf.next_action+'</p>';if(wf.allowed_actions&&wf.allowed_actions.length){html+='<div class="workflow-actions">';wf.allowed_actions.forEach(function(a){var label=a.replace(/_/g,' ').replace(/\b\w/g,function(c){return c.toUpperCase()});html+='<button class="'+(a.indexOf('approve')>=0?'primary':'secondary')+'" onclick="workflowAction(\''+a+'\')">'+label+'</button>'});html+='</div>'}card.innerHTML=html;window.currentWorkflow=wf;}
window.workflowAction=async function(action){if(!window.currentWorkflow)return;var target=action==='approve_mission'?'repository_audit':window.currentWorkflow.current_stage;show('Workflow action: '+action);try{var data=await post('/mission-control/founder-workflows/advance',{token:token,workflow_id:window.currentWorkflow.workflow_id,title:window.currentWorkflow.title,workflow_type:window.currentWorkflow.workflow_type,target_stage:target,approval_status:action.indexOf('approve')>=0?'approved':'pending'});show(data);if(data.workflow)renderWorkflowCard(data.workflow)}catch(e){show('Workflow action failed: '+e)}};
function fillMinutes(text,meeting){var mode=classifyConversation(text);var pill=byId('conversationMode');if(pill)pill.textContent=mode[0];var desc=byId('modeDescription');if(desc)desc.textContent=mode[1];var suggest=byId('missionSuggestion');if(suggest)suggest.textContent=mode[2];var card=byId('missionCard');if(card){var needs=/Engineering Mission|Deployment/.test(mode[0]);card.className='mission-card '+(needs?'ready':'muted');card.textContent=needs?'Suggested next step: generate a workflow after Founder confirms scope.':'Working note only. Do not auto-create a mission.'}var meta=byId('meetingMeta');if(meta)meta.textContent=meeting||'No meeting yet.'}
window.newBoardChat=function(){if(byId('message'))byId('message').value='';show('New Board Room chat started.');fillMinutes('','No meeting yet.');var wc=byId('workflowCard');if(wc){wc.className='mission-card muted';wc.textContent='Workflow card will appear after Generate Workflow.'}openBoardRoom()};window.openBoardRoom=function(){byId('boardModal').classList.add('active')};window.closeBoardRoom=function(){byId('boardModal').classList.remove('active')};window.startCommand=function(){byId('message').value=byId('commandInput').value||'';fillMinutes(byId('message').value,'Draft message');openBoardRoom()};"""
